8	/** The plain finding object the checks runner consumes (engine/checks/README.md). */
9	export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
10	  return {
11	    rule: rule.id,
12	    severity: severity || rule.severity,
13	    file,
14	    line,
15	    what,
16	    why: why || rule.why,
17	    fix,
18	    doc: rule.doc,
19	  };
20	}
