3	// `suppressLocalAudioPlayback` and `restrictOwnAudio` are `getDisplayMedia`
4	// SCREEN-CAPTURE constraints. They filter the playout of a captured tab out of
5	// that tab's audio track; they say nothing about a microphone, and getUserMedia
6	// ignores them entirely — no throw, no warning, no `OverconstrainedError`.
7	//
8	// They are reached for by name: someone hunting the app's own TTS leaking back
9	// through the mic reads "suppress local audio playback" / "restrict own audio"
10	// as exactly the fix, sets it on the mic capture, and ships believing self-echo
11	// is handled at the capture layer. It isn't, and the code that would have
12	// handled it (an application-level echo guard) never gets written. That is the
13	// silent-failure shape this whole pack is about: nothing throws, nothing logs,
14	// the feature simply doesn't exist.
15	//
16	// PARSED, NOT GREPPED. The names are only wrong where they reach a microphone
17	// capture, so the scan is the balanced argument list of a `getUserMedia(` call —
18	// plus, one hop, the initializer of any same-file constant that argument list
19	// references, since hoisting the constraints into a frozen constant is the
20	// ordinary way to write this:
21	//
22	//     const AUDIO = Object.freeze({ echoCancellation: true });
23	//     await media.getUserMedia({ audio: AUDIO });
24	//
25	// Everything outside that reach stays quiet on purpose — a file's real
26	// getDisplayMedia call, a `getSupportedConstraints()` probe, a screen-capture
27	// module's own constants table are all legitimate uses of these names, and a
28	// rule that grepped the file would false-alarm on every one of them. Comments
29	// are stripped first, so the paragraphs above cannot fire the rule.
30	
31	const CALL = /\bgetUserMedia\s*\(/g;
32	const DECL = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g;
33	const OPENER = /^\s*(?:[A-Za-z_$][\w$.]*\s*)?([[{(])/;
34	const DISPLAY_ONLY = ['suppressLocalAudioPlayback', 'restrictOwnAudio'];
35	
36	/**
37	 * The index ranges of `src` that a getUserMedia call's constraints actually
38	 * reach: the argument list itself, plus the initializer of every same-file
39	 * `const`/`let`/`var` the argument list names. One hop only — resolving further
40	 * needs real data-flow analysis, and a check that guesses is worse than one that
41	 * asks a simple, honest question.
42	 */
43	function reach(src, argsStart, args) {
44	  const regions = [{ start: argsStart, end: argsStart + args.length }];
45	  DECL.lastIndex = 0;
46	  for (let d = DECL.exec(src); d; d = DECL.exec(src)) {
47	    if (!new RegExp(`\\b${d[1]}\\b`).test(args)) continue;
48	    const eq = d.index + d[0].length;
49	    const head = OPENER.exec(src.slice(eq));
50	    if (!head) continue;
51	    const open = eq + head[0].length - 1;
52	    const init = balanced(src, open);
53	    if (init === null) continue;
54	    regions.push({ start: open, end: open + init.length });
55	  }
56	  return regions;
57	}
