    if (lastInterimAt && Date.now() - lastInterimAt >= pauseResetMs) {
      settle({ error: 'reset' }); // REQ-SPCH-010: discard and start fresh
      try {
        rec.abort();
      } catch { /* already gone */ }
    }
  }, Math.min(100, pauseResetMs));
}

